import json, csv, datetime
import pandas as pd

def norm_date(v):
    if v is None:
        return None
    if isinstance(v, (datetime.date, datetime.datetime)):
        return v.strftime('%Y-%m-%d')
    s = str(v).strip()
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%d-%m-%Y', '%m/%d/%Y', '%d/%m/%Y'):
        try:
            return datetime.datetime.strptime(s, fmt).strftime('%Y-%m-%d')
        except ValueError:
            pass
    try:
        return pd.to_datetime(s).strftime('%Y-%m-%d')
    except Exception:
        return s

def norm_status(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return 'active' if v else 'inactive'
    s = str(v).strip()
    if s.lower() in ('true', '1'):
        return 'active'
    if s.lower() in ('false', '0'):
        return 'inactive'
    return s

FIELDS = ['user_id', 'name', 'email', 'created_date', 'status']

def mkrec(user_id, name, email, created_date, status):
    return {
        'user_id': int(user_id),
        'name': None if name is None else str(name),
        'email': None if email is None else str(email),
        'created_date': norm_date(created_date),
        'status': norm_status(status),
    }

# source_a: json
with open('/data/source_a/users.json') as f:
    a_raw = json.load(f)
a = {}
for r in a_raw:
    rec = mkrec(r.get('id'), r.get('full_name'), r.get('email'), r.get('registration_date'), r.get('status'))
    a[rec['user_id']] = rec

# source_b: csv
b = {}
with open('/data/source_b/users.csv', newline='') as f:
    for r in csv.DictReader(f):
        rec = mkrec(r.get('user_id'), r.get('name'), r.get('email_address'), r.get('created_at'), r.get('is_active'))
        b[rec['user_id']] = rec

# source_c: parquet
c = {}
cdf = pd.read_parquet('/data/source_c/users.parquet')
for _, r in cdf.iterrows():
    rec = mkrec(r['userId'], r['userName'], r['email'], r['joined'], r['active'])
    c[rec['user_id']] = rec

sources = {'source_a': a, 'source_b': b, 'source_c': c}
priority = ['source_a', 'source_b', 'source_c']

all_ids = sorted(set(a) | set(b) | set(c))

merged = []
conflicts = []
for uid in all_ids:
    present = [s for s in priority if uid in sources[s]]
    final = {'user_id': uid}
    for field in ['name', 'email', 'created_date', 'status']:
        vals = {}
        for s in present:
            v = sources[s][uid].get(field)
            if v is not None:
                vals[s] = v
        # selected: highest priority present with non-None value
        selected = None
        for s in priority:
            if s in vals:
                selected = vals[s]
                break
        final[field] = selected
        # conflict if more than one source has a value and they differ
        distinct = set(vals.values())
        if len(vals) > 1 and len(distinct) > 1:
            conflicts.append({
                'user_id': uid,
                'field': field,
                'values': {s: vals[s] for s in priority if s in vals},
                'selected': selected,
            })
    merged.append(final)

mdf = pd.DataFrame(merged, columns=FIELDS)
mdf['user_id'] = mdf['user_id'].astype('int64')
for col in ['name', 'email', 'created_date', 'status']:
    mdf[col] = mdf[col].astype('object')
mdf.to_parquet('/app/merged_users.parquet', index=False)

report = {'total_conflicts': len(conflicts), 'conflicts': conflicts}
with open('/app/conflicts.json', 'w') as f:
    json.dump(report, f, indent=2)

print(mdf.to_string())
print(json.dumps(report, indent=2))

